90	fn determine_applicability(binding: &Binding, scope: &Scope, checker: &Checker) -> Applicability {
91	    // If it's not in a module scope, the import can't be implicitly re-exported,
92	    // so always mark it as safe
93	    if !scope.kind.is_module() {
94	        return Applicability::Safe;
95	    }
96	    // If it's not a stub and it's in the module scope, always mark the fix as unsafe
97	    if !checker.source_type.is_stub() {
98	        return Applicability::Unsafe;
99	    }
100	    // If the import was `from collections.abc import Set as Set`,
101	    // it's being explicitly re-exported: mark the fix as unsafe
102	    if binding.is_explicit_export() {
103	        return Applicability::Unsafe;
104	    }
105	    // If it's included in `__all__`, mark the fix as unsafe
106	    if binding.references().any(|reference| {
107	        checker
108	            .semantic()
109	            .reference(reference)
110	            .in_dunder_all_definition()
111	    }) {
112	        return Applicability::Unsafe;
113	    }
114	    // Anything else in a stub, and it's a safe fix:
115	    Applicability::Safe
116	}
