/// Detect conflicts between I002 (missing-required-import) and lint rules that
/// require a required import to be aliased in a specific way.
///
/// Currently this only covers PYI025 (unaliased-collections-abc-set-import),
/// which requires `from collections.abc import Set` to be aliased as
/// `AbstractSet`.
fn conflicting_required_import_rules(
    isort: &isort::settings::Settings,
    rules: &RuleTable,
) -> Result<()> {
    if !rules.enabled(Rule::UnaliasedCollectionsAbcSetImport) {
        return Ok(());
    }

    for required_import in &isort.required_imports {
        if required_import.qualified_name().segments() == ["collections", "abc", "Set"]
            && required_import.bound_name() != "AbstractSet"
        {
            return Err(anyhow!(
                "Required import `from collections.abc import Set` specified in \
                `lint.isort.required-imports` (I002) conflicts with \
                `unaliased-collections-abc-set-import` (PYI025), which requires this \
                import to be aliased as `AbstractSet`.\n\
                Help: Either alias the required import \
                (`from collections.abc import Set as AbstractSet`), or disable PYI025."
            ));
        }
    }

    Ok(())
}

